const article = $('Loop Over Items1').item.json;
const out = [];

const esc = (s) => String(s || '').replace(/'/g, "''");

for (const item of $input.all()) {
  let raw = item.json.content || item.json.message?.content || '';
  let clean = raw.replace(/```json/ig, '').replace(/```/g, '').trim().replace(/\\'/g, "'");
  const parsed = JSON.parse(clean);

  const mots = JSON.stringify(parsed.mots_cles || []);

  out.push({ json: {
    article_id:      article.id,
    theme_principal: esc(parsed.theme_principal || 'Autre'),
    public_cible:    esc(parsed.public_cible    || 'Toutes entreprises'),
    titre_article:   esc(parsed.titre_article   || article.titre_brut || 'Sans titre'),
    resume_court:    esc(parsed.resume_court    || ''),
    resume_long:     esc(parsed.resume_long     || ''),
    mots_cles:       esc(mots)
  }});
}
return out;

